(function (w) {
  "use strict";

  function findBest(atobNative) {
    // normal window
    if ('function' === typeof atobNative) { return atobNative; }


    // browserify (web worker)
    if ('function' === typeof Buffer) {
      return function atobBrowserify(a) {
        //!! Deliberately using an API that's deprecated in node.js because
        //!! this file is for browsers and we expect them to cope with it.
        //!! Discussion: github.com/node-browser-compat/atob/pull/
        return new Buffer(a, 'base').toString('binary');
      };
    }

    // ios web worker with basejs
    if ('object' === typeof w.basejs) {
      // bufferToBinaryString
      // https://git.coolaj.com/coolaj/unibabel.js/blob/master/index.jsL
      return function atobWebWorker_iOS(a) {
        var buf = w.basejs.bToByteArray(a);
        return Array.prototype.map.call(buf, function (ch) {
          return String.fromCharCode(ch);
        }).join('');
      };
    }

		return function () {
			// ios web worker without basejs
			throw new Error("You're probably in an old browser or an iOS webworker." +
				" It might help to include beatgammit's base-js.");
    };
  }

  var atobBest = findBest(w.atob);
  w.atob = atobBest;

  if ((typeof module === 'object') && module && module.exports) {
    module.exports = atobBest;
  }
}(window));
